CREATE TABLE dates(d DATE,t TIME(3),ts TIMESTAMP(3));
INSERT INTO dates VALUES(DATE '2016-01-01',TIME '12:34:56.123',TIMESTAMP '2016-01-01 12:34:56.123');
SELECT DATE_TRUNC(month,d),DATE_TRUNC(ms,t),DATE_TRUNC(second,ts),LAST_DAY(d),EXTRACT(iso_year FROM d),EXTRACT(epoch FROM ts) FROM dates;
CREATE TABLE bounds AS SELECT DATE_TRUNC(month,d) AS d,LAST_DAY(ts) AS last_day,EXTRACT(epoch FROM ts) AS e FROM dates;
TABLE bounds;
SELECT DATE_TRUNC(month,d) AS d FROM dates UNION SELECT DATE '2016-01-01';
WITH q(d) AS (TABLE dates) SELECT LAST_DAY(d) AS d FROM q;
SELECT LAST_DAY(MAX(d)) AS d,EXTRACT(iso_week FROM MAX(d)) AS w FROM dates;
CREATE TABLE saved(first_day DATE DEFAULT DATE_TRUNC(month,(SELECT MAX(d) FROM dates)),last_day DATE DEFAULT LAST_DAY((SELECT MAX(d) FROM dates)),epoch NUMERIC(28,9) DEFAULT EXTRACT(epoch FROM (SELECT MAX(d) FROM dates)));
INSERT INTO saved DEFAULT VALUES;
UPDATE dates SET d=DATE '2000-02-15';
INSERT INTO saved DEFAULT VALUES;
TABLE saved ORDER BY first_day;
